import { Fragment, useEffect, useMemo, useState } from 'react'
import { ANALYSIS_STEPS, FESTIVAL_TYPES, FLOW, MONTHS, PROGRAMS, REGIONS, SAMPLE, YEARS, analyze, getLevel } from './data/prototype'

const fmt = (n) => Math.round(Number(n) || 0).toLocaleString('ko-KR')
const round1 = (n) => Math.round(n * 10) / 10
const dfmt = (d) => `${d.getMonth() + 1}월 ${d.getDate()}일`
const dadd = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x }
const dparse = (s) => { const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d) }
const levelClass = (level) => `pill ${level}`

function Header({ stage, onHome }) {
  const active = FLOW.findIndex(([key]) => key === stage)
  return <header className="topbar"><div className="brand" onClick={onHome} onKeyDown={(e) => (e.key === 'Enter' || e.key === ' ') && onHome()} role="button" tabIndex="0" aria-label="FestivalScope 처음으로">Festival<span>Scope</span><em>축제 흥행 사전 검증</em></div><nav className="flow" aria-label="분석 진행 단계">{FLOW.map(([key, label], i) => <Fragment key={key}>{i > 0 && <i className="flow-sep" />}<span className={`flow-step ${i === active ? 'on' : i < active ? 'done' : ''}`}><b>{i < active ? '✓' : i + 1}</b>{label}</span></Fragment>)}</nav><div className="topbar-right"><span className="mockbadge">예시 데이터로 동작하는 프로토타입</span></div></header>
}
function Button({ children, primary = false, ghost = false, small = false, ...props }) { return <button className={`btn ${primary ? 'btn-primary' : ''} ${ghost ? 'btn-ghost' : ''} ${small ? 'btn-sm' : ''}`} {...props}>{children}</button> }
function Input({ label, required, hint, error, full = false, children }) { return <div className={`field ${full ? 'full ' : ''}${error ? 'err' : ''}`}><label>{label} {required && <span className="req">필수</span>} {hint && <span className="hint">{hint}</span>}</label>{children}</div> }

const themeLabel = (pair) => `${FESTIVAL_TYPES[pair.type] || pair.type || '미입력'} · ${pair.topic || '미입력'}`
const eventTypeLabel = (eventType) => eventType === 'new' ? '신규 개최' : '기존 개최'

function FormScreen({ plan, setPlan, step, setStep, onReview }) {
  const [errors, setErrors] = useState([]); const update = (k, v) => setPlan((p) => ({ ...p, [k]: v })); const pairs = plan.festivalThemes?.length ? plan.festivalThemes : [{ type: '', topic: '' }]
  const updateEventType = (eventType) => setPlan((p) => ({ ...p, eventType, firstHeldYear: eventType === 'new' ? null : p.firstHeldYear }))
  const updatePair = (index, key, value) => setPlan((p) => ({ ...p, festivalThemes: (p.festivalThemes?.length ? p.festivalThemes : [{ type: '', topic: '' }]).map((pair, i) => i === index ? { ...pair, [key]: value } : pair) }))
  const addPair = () => setPlan((p) => p.festivalThemes.length < 2 ? { ...p, festivalThemes: [...p.festivalThemes, { type: '', topic: '' }] } : p)
  const removePair = (index) => setPlan((p) => p.festivalThemes.length > 1 ? { ...p, festivalThemes: p.festivalThemes.filter((_, i) => i !== index) } : p)
  const validate = () => { const e = []; if (step >= 1 && !plan.name.trim()) e.push('축제명'); if (step >= 1 && !plan.target) e.push('목표 방문객'); if (step >= 1 && pairs.some((pair) => !pair.type || !pair.topic.trim())) e.push('축제 유형 및 주제'); if (step >= 1 && plan.eventType === 'existing' && (!Number.isInteger(Number(plan.firstHeldYear)) || Number(plan.firstHeldYear) < 1000 || Number(plan.firstHeldYear) > new Date().getFullYear())) e.push('최초 개최 이력(4자리 연도)'); if (step >= 2 && !plan.venue.trim()) e.push('행사장명'); if (step >= 2 && !plan.start) e.push('개최 시작일'); if (step >= 2 && !plan.end) e.push('개최 종료일'); if (step >= 2 && plan.start && plan.end && plan.end < plan.start) e.push('개최 종료일(시작일보다 빠름)'); if (step >= 3 && !plan.programs.length) e.push('프로그램 구성'); setErrors(e); return !e.length }
  const next = () => { if (!validate()) return; step < 3 ? setStep(step + 1) : onReview({ ...plan }) }
  const toggle = (id) => { const programs = plan.programs.includes(id) ? plan.programs.filter((x) => x !== id) : [...plan.programs, id]; update('programs', programs); if (programs.length) update('outdoor', Math.round(PROGRAMS.filter((x) => programs.includes(x.id) && x.out).length / programs.length * 20) * 5) }
  const names = ['축제 기본 정보', '개최 일정 · 장소', '프로그램 · 운영']
  return <main className="screen active"><div className="wrap"><h1 className="page-h">축제 기획안 입력</h1><p className="page-sub page-lead">분석에 쓰이는 값만 받습니다. 목표 방문객·개최 일정·지역·행사장·주제·프로그램 구성이 비면 분석을 실행할 수 없습니다.</p><div className="formcard"><div className="formhead"><div className="steps">{names.map((n, i) => <span className={`stepchip ${step === i + 1 ? 'on' : ''} ${step > i + 1 ? 'ok' : ''}`} key={n}><b>{step > i + 1 ? '✓' : i + 1}</b>{n}</span>)}</div><span className="lbl">{step} / 3 단계</span></div>{errors.length > 0 && <div className="alert show"><b>분석에 필요한 정보가 비어 있습니다</b><ul>{errors.map((e) => <li key={e}>{e}</li>)}</ul></div>}
    {step === 1 && <div className="fieldgrid"><Input full label="축제명" required error={errors.includes('축제명')}><input type="text" value={plan.name} onChange={(e) => update('name', e.target.value)} placeholder="예: 영월 가을별빛 야행축제" /></Input><Input label="주최 기관"><input type="text" value={plan.org} onChange={(e) => update('org', e.target.value)} placeholder="예: 강원특별자치도 영월군" /></Input><Input full label="축제 유형 및 주제" required hint="트렌드 핏 분석 기준"><div className="theme-pairs">{pairs.map((pair, index) => <div className="theme-pair" key={`theme-${index}`}><div className="theme-pair-fields"><select aria-label={`축제 유형 ${index + 1}`} value={pair.type} onChange={(e) => updatePair(index, 'type', e.target.value)}><option value="">축제 유형 선택</option>{Object.entries(FESTIVAL_TYPES).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select><input type="text" aria-label={`축제 주제 ${index + 1}`} value={pair.topic} onChange={(e) => updatePair(index, 'topic', e.target.value)} placeholder="예: 별빛·천문" /></div>{index === 0 && <Button type="button" small onClick={addPair} disabled={pairs.length >= 2} aria-label="축제 유형 및 주제 추가">+</Button>}{index > 0 && <Button type="button" small onClick={() => removePair(index)} aria-label={`축제 유형 및 주제 ${index + 1} 삭제`}>−</Button>}</div>)}</div></Input><Input label="목표 방문객" required hint="전체 기간 누적" error={errors.includes('목표 방문객')}><input type="number" min="1000" step="1000" value={plan.target || ''} onChange={(e) => update('target', Number(e.target.value))} placeholder="120000" /></Input><Input label="개최 형태" required error={errors.includes('최초 개최 이력(4자리 연도)')}><div className="event-type-and-history"><div className="event-type-options"><label className={`event-type-option ${plan.eventType === 'existing' ? 'on' : ''}`}><input type="radio" name="eventType" value="existing" checked={plan.eventType === 'existing'} onChange={(e) => updateEventType(e.target.value)} />기존 개최</label><label className={`event-type-option ${plan.eventType === 'new' ? 'on' : ''}`}><input type="radio" name="eventType" value="new" checked={plan.eventType === 'new'} onChange={(e) => updateEventType(e.target.value)} />신규 개최</label></div>{plan.eventType === 'existing' && <div className="event-history-inline"><label htmlFor="firstHeldYear">최초 개최 이력</label><input id="firstHeldYear" type="number" min="1000" max={new Date().getFullYear()} inputMode="numeric" value={plan.firstHeldYear || ''} onChange={(e) => update('firstHeldYear', e.target.value ? Number(e.target.value) : null)} placeholder="예: 2018" /></div>}</div></Input></div>}
    {step === 2 && <div className="fieldgrid"><Input label="개최 지역" required><select value={plan.region} onChange={(e) => update('region', e.target.value)}>{Object.entries(REGIONS).map(([k, r]) => <option key={k} value={k}>{r.name}</option>)}</select></Input><Input label="행사장 유형"><select value={plan.venueType} onChange={(e) => update('venueType', e.target.value)}><option value="outdoor">야외 (하천변·광장·공원)</option><option value="mixed">혼합 (야외 + 실내 시설)</option><option value="indoor">실내 중심</option></select></Input><Input full label="행사장명" required error={errors.includes('행사장명')}><input type="text" value={plan.venue} onChange={(e) => update('venue', e.target.value)} placeholder="예: 동강둔치 일원" /></Input><Input label="개최 시작일" required error={errors.includes('개최 시작일')}><input type="date" value={plan.start} onChange={(e) => update('start', e.target.value)} /></Input><Input label="개최 종료일" required error={errors.includes('개최 종료일')}><input type="date" value={plan.end} onChange={(e) => update('end', e.target.value)} /></Input><Input full label="확보 주차면수" hint="접근성 판단에 사용"><input type="number" min="0" step="50" value={plan.parking || ''} onChange={(e) => update('parking', Number(e.target.value))} placeholder="1150" /></Input></div>}
    {step === 3 && <div className="fieldgrid"><Input full label="프로그램 구성" required hint="하나 이상 선택" error={errors.includes('프로그램 구성')}><div className="chips">{PROGRAMS.map((p) => <label className={`chk ${plan.programs.includes(p.id) ? 'on' : ''}`} key={p.id}><input type="checkbox" checked={plan.programs.includes(p.id)} onChange={() => toggle(p.id)} />{p.n}</label>)}</div></Input><Input full label="야외 프로그램 비중"><div className="rangerow"><input type="range" min="0" max="100" step="5" value={plan.outdoor} onChange={(e) => update('outdoor', Number(e.target.value))} /><span className="rangeval">{plan.outdoor}%</span></div></Input><Input label="우천 대안"><select value={plan.rainplan} onChange={(e) => update('rainplan', e.target.value)}><option value="none">없음</option><option value="partial">일부 확보 (대체 공간 지정)</option><option value="full">충분 (전 프로그램 대체 동선 확보)</option></select></Input><Input label="실내 대체공간 수용 인원" hint="동시 수용 기준"><input type="number" min="0" step="50" value={plan.shelter || ''} onChange={(e) => update('shelter', Number(e.target.value))} placeholder="300" /></Input></div>}
    <div className="formfoot"><Button onClick={() => setStep(Math.max(1, step - 1))} style={{ visibility: step === 1 ? 'hidden' : 'visible' }}>이전</Button><span className="spacer" /><Button ghost small onClick={() => { setPlan(SAMPLE); setErrors([]) }}>예시 기획안 채우기</Button><Button primary onClick={next}>{step === 3 ? '입력 확인' : '다음'}</Button></div></div></div></main>
}

function ReviewScreen({ plan, onEdit, onAnalyze }) { const R = REGIONS[plan.region], days = Math.max(1, Math.round((new Date(plan.end) - new Date(plan.start)) / 86400000) + 1); const rows = [['주최 기관', plan.org ? plan.org : <small>미입력</small>], ['축제 유형 및 주제', <div className="review-themes">{plan.festivalThemes.map((pair, index) => <div key={`review-theme-${index}`}>{index + 1}. {themeLabel(pair)}</div>)}</div>], ['개최 형태', <>{eventTypeLabel(plan.eventType)}{plan.eventType === 'existing' && plan.firstHeldYear ? <small> · 최초 개최 {plan.firstHeldYear}년</small> : null}</>], ['목표 방문객', <>{fmt(plan.target)}명 <small>· 일평균 {fmt(plan.target / days)}명</small></>], ['개최 일정', <>{plan.start} ~ {plan.end} <small>· {days}일</small></>], ['개최 지역', R.name], ['행사장', <>{plan.venue} <small>· {plan.venueType === 'outdoor' ? '야외' : plan.venueType === 'mixed' ? '혼합' : '실내 중심'}</small></>], ['확보 주차면수', `${fmt(plan.parking)}면`], ['프로그램 구성', PROGRAMS.filter((p) => plan.programs.includes(p.id)).map((p) => p.n).join(', ')], ['야외 프로그램 비중', `${plan.outdoor}%`], ['우천 대안', <>{plan.rainplan === 'none' ? '없음' : plan.rainplan === 'partial' ? '일부 확보' : '충분'} <small>· 실내 대체 {fmt(plan.shelter)}명</small></>]]; return <main className="screen active"><div className="wrap"><h1 className="page-h">입력 정보 확인</h1><p className="page-sub page-lead">이 값으로 6개 항목을 분석합니다. 값이 바뀌면 결과도 바뀝니다.</p><div className="formcard"><div className="formhead"><h3 className="sec-h">{plan.name}</h3><Button small onClick={onEdit}>기획안 수정</Button></div><div className="reviewgrid">{rows.map(([l, v]) => <div className="rv" key={l}><div className="lbl">{l}</div><div className="v">{v}</div></div>)}</div><div className="formfoot"><span className="lbl">분석은 과거 데이터 기반의 타당성·리스크 진단이며 미래 흥행을 보장하지 않습니다.</span><span className="spacer" /><Button primary onClick={onAnalyze}>분석 실행</Button></div></div></div></main> }
function LoadingScreen({ plan, onDone }) { const [active, setActive] = useState(0); useEffect(() => { const t = setInterval(() => setActive((v) => v + 1), 450); return () => clearInterval(t) }, []); useEffect(() => { if (active > ANALYSIS_STEPS.length) { const t = setTimeout(onDone, 380); return () => clearTimeout(t) } return undefined }, [active, onDone]); return <main className="screen active"><div className="analysing"><h2 className="an-h">{plan.name} 분석 중</h2><p className="an-sub">유사 축제·관심도·관광수요·행사 이력·기상 통계·주변 POI를 순서대로 조회합니다.</p><div className="an-list">{ANALYSIS_STEPS.map((x, i) => <div className={`an-item ${i < active ? 'fin' : i === active ? 'run' : ''}`} key={x}><span className="dot" />{x}</div>)}</div><div className="progbar"><i style={{ width: `${Math.min(100, active / ANALYSIS_STEPS.length * 100)}%` }} /></div></div></main> }

const ITEMS = [{ key: 'visitor', no: 1, scored: true, name: '목표 방문객 타당성', scope: '유사 축제의 실제 방문객 규모와 연도별 추이 비교' }, { key: 'trend', no: 2, scored: true, name: '트렌드 핏', scope: '축제 주제·프로그램 관련 검색 관심도의 최근 5년 추이' }, { key: 'demand', no: 3, scored: true, name: '지역·시기 관광수요 적합성', scope: '평상시 지역 관광수요 · 최근 5년 월별 관광수요 · 행사장 접근성' }, { key: 'overlap', no: 4, scored: false, name: '일정 중복·혼잡 리스크', scope: '최근 5년 동일 시기 · 인접 권역(반경 80km) 행사 이력' }, { key: 'weather', no: 5, scored: false, name: '날씨 리스크', scope: '과거 동일 시기 기상 통계 × 야외 프로그램 비중 · 우천 대안' }, { key: 'link', no: 6, scored: false, name: '관광 연계 잠재력', scope: '행사장 반경 5km · 15km 관광지 · 음식점 상권 · 숙박 POI' }]
function cardData(item, A) { const v = A.v; if (item.key === 'visitor') return { pill: v.v1, tone: v.v1 === '적정 범위' ? 'g' : v.ratio > 1.6 || v.ratio < .5 ? 'r' : 'w', metric: `${round1(v.ratio)}배`, unit: '유사 축제 중위값 대비', sub: [['목표', `${fmt(A.p.target)}명`], ['중위값', `${fmt(v.median)}명`], ['점수', v.s1]], read: v.ratio > 1.3 ? `유사 축제 중위값 ${fmt(v.median)}명을 ${round1(v.ratio)}배 웃도는 목표입니다. 예산·인력 산정 근거가 약해질 수 있습니다.` : v.ratio < .8 ? '유사 축제 대비 보수적인 목표입니다. 운영 준비 여력은 있으나 사업 규모 설득에 불리할 수 있습니다.' : '유사 축제의 실제 규모 범위 안에 있는 목표입니다.', bars: [v.median, A.p.target] }; if (item.key === 'trend') return { pill: v.v2, tone: v.v2 === '상승' ? 'g' : v.v2 === '유지' ? 'w' : 'r', metric: A.T.series[4], unit: '관심도 지수 (2026)', sub: [['5년 추이', `${v.tCagr > 0 ? '+' : ''}${(v.tCagr * 100).toFixed(1)}%/년`], ['점수', v.s2]], read: v.v2 === '상승' ? `${A.T.name} 주제의 검색 관심도가 5년 연속 올라 관심 흐름과 방향이 맞습니다.` : v.v2 === '유지' ? '관심도가 뚜렷한 방향 없이 유지되고 있습니다. 주제만으로는 신규 방문 동인이 약합니다.' : '관심도가 지속 하락 중입니다. 주제 구성을 그대로 두면 신규 유입이 어려울 수 있습니다.', bars: A.T.series }; if (item.key === 'demand') return { pill: v.v3, tone: v.v3 === '적합' ? 'g' : v.v3 === '조건부 적합' ? 'w' : 'r', metric: v.s3, unit: '적합성 점수 / 100', sub: [[`${A.m + 1}월 수요`, `지수 ${v.mIdx} (연중 ${v.mRank}위)`], ['접근성', v.accScore]], read: `개최 월 수요는 연중 ${v.mRank}위로 ${v.mIdx >= 110 ? '유리' : '평이'}하지만, ${v.accScore < 60 ? `행사장 접근성(${v.accScore}점)이 전체 점수를 끌어내립니다.` : '접근성도 무리 없는 수준입니다.'}`, bars: A.R.monthly, highlight: A.m }; if (item.key === 'overlap') return { pill: `위험 ${v.v4}`, tone: v.v4 === '높음' ? 'r' : v.v4 === '보통' ? 'w' : 'g', metric: v.nDirect + v.nNear, unit: '중복 가능 행사', sub: [['기간 직접 중복', `${v.nDirect}건`], ['±3일 인접', `${v.nNear}건`]], read: v.nDirect ? `개최 기간에 반경 60km 내 행사 ${v.nDirect}건이 겹칩니다. 관람객 분산과 숙박 경합이 예상됩니다.` : v.nNear ? `직접 겹치는 행사는 없으나 전후 3일 내 인접 권역 행사가 ${v.nNear}건 있습니다.` : '반경 80km 내에서 같은 시기에 반복 개최되는 행사가 확인되지 않았습니다.', bars: [] }; if (item.key === 'weather') return { pill: `취약도 ${v.v5}`, tone: v.v5 === '높음' ? 'r' : v.v5 === '보통' ? 'w' : 'g', metric: `${v.rainP}%`, unit: `${A.m + 1}월 동일 시기 강수 발생률`, sub: [['야외 비중', `${A.p.outdoor}%`], ['실내 대체 수용률', `${Math.round(v.shelterCov)}%`]], read: `야외 비중 ${A.p.outdoor}%에 실내 대체 수용률이 ${Math.round(v.shelterCov)}%여서, 강수 시 ${v.shelterCov < 30 ? '프로그램 대부분이 중단됩니다.' : '일부 프로그램만 대체 운영이 가능합니다.'}`, bars: A.R.weather.rainYears, highlight: A.m }; const P = A.R.poi; return { pill: `잠재력 ${v.v6}`, tone: v.v6 === '높음' ? 'g' : v.v6 === '보통' ? 'w' : 'r', metric: P.r15.tour + P.r15.stay, unit: '반경 15km 연계 가능 자원', sub: [['관광지', `${P.r15.tour}곳`], ['숙박', `${P.r15.stay}곳`], ['체류 수용률', `${Math.round(v.stayCov)}%`]], read: `관광지 밀도는 ${v.tourS >= 70 ? '충분' : '보통'}하지만 숙박 수용은 일평균 방문객의 ${Math.round(v.stayCov)}% 수준입니다.`, bars: [] } }

function MiniBars({ values = [], highlight = null }) { const max = Math.max(...values, 1); return <div className="minibars" aria-hidden="true">{values.map((v, i) => <i key={`${v}-${i}`} className={highlight === null ? (i === values.length - 1 ? 'hi' : '') : i === highlight ? 'hi' : ''} style={{ height: `${Math.max(8, v / max * 30)}px` }} />)}</div> }
function VisitorBars({ values, maxValue }) { const max = maxValue || Math.max(...values, 1); return <svg className="spark" viewBox="0 0 200 30" preserveAspectRatio="none" aria-hidden="true"><rect x="0" y="3" width={values[0] / max * 200} height="9" rx="1" fill="#CBDCE8" /><rect x="0" y="17" width={values[1] / max * 200} height="9" rx="1" fill="#12557E" /></svg> }
function Sparkline({ values, color = '#12557E' }) { const max = Math.max(...values), min = Math.min(...values) * .92, pts = values.map((v, i) => `${i * (120 / (values.length - 1))},${30 - 2 - ((v - min) / (max - min || 1)) * 24}`).join(' '); return <svg className="spark" viewBox="0 0 120 30" preserveAspectRatio="none" aria-hidden="true"><polygon points={`0,30 ${pts} 120,30`} fill={color} opacity=".10" /><polyline points={pts} fill="none" stroke={color} strokeWidth="1.8" /><circle cx="120" cy={30 - 2 - ((values[values.length - 1] - min) / (max - min || 1)) * 24} r="2.6" fill={color} /></svg> }
function ResultCard({ item, A, onOpen, selected }) { const d = cardData(item, A); return <button className={`card ${selected ? 'sel' : ''}`} onClick={() => onOpen(item.key)}><div className="card-top"><span className="card-name">{item.no}. {item.name}</span><span className={levelClass(d.tone)}>{d.pill}</span></div><div className="card-metric"><b>{d.metric}</b><span>{d.unit}</span></div><div className="card-sub">{d.sub.map(([l, v]) => <span key={l}><em>{l}</em> {v}</span>)}</div>{item.key === 'visitor' && <VisitorBars values={d.bars} maxValue={Math.max(A.v.median, A.p.target, A.v.top) * 1.06} />}{item.key === 'trend' && <Sparkline values={d.bars} color={d.tone === 'r' ? '#C2634C' : '#12557E'} />}{item.key === 'demand' && <MiniBars values={d.bars} highlight={d.highlight} />}{item.key === 'weather' && <MiniBars values={d.bars} highlight={d.highlight} />}<div className="card-read">{d.read}</div><div className="card-open">상세 근거 보기</div></button> }

function ResultScreen({ A, onEdit, onReport, onOpen, openKey }) { const rows = [['목표 방문객 타당성', A.v.s1], ['트렌드 핏', A.v.s2], ['지역·시기 관광수요', A.v.s3]]; return <main className="screen active"><div className="wrap-wide"><div className="plan-bar"><div><div className="plan-title">{A.p.name}</div><div className="plan-meta">{A.R.name} · {A.p.venue}<i>|</i>{A.p.start} ~ {A.p.end} ({A.days}일)<i>|</i>목표 {fmt(A.p.target)}명<i>|</i>{A.T.name}</div></div><span className="spacer" /><Button small onClick={onEdit}>기획안 보완하기</Button><Button small primary onClick={onReport}>최종 리포트</Button></div><div className="scorehead"><div className="score-left"><span className="lbl">종합 흥행 스코어</span><div className="score-val"><b>{A.composite}</b><span>/ 100</span></div><span className={`grade pill ${A.composite >= 75 ? 'g' : A.composite >= 62 ? 'w' : 'r'}`}>등급 {A.grade} · {A.gradeNote}</span></div><div className="score-right"><div className="rail">{rows.map(([l, v]) => <div className="railrow" key={l}><span className="rn">{l}</span><span className={`track ${getLevel(v)}`}><i style={{ width: `${v}%` }} /></span><span className="rv2">{v}</span></div>)}</div><p className="score-note">3개 항목의 동일 가중 평균입니다. 별도 진단 3건(일정 중복 {A.v.v4} · 날씨 취약도 {A.v.v5} · 관광 연계 {A.v.v6})은 스코어에 반영되지 않습니다.</p></div></div><Group title="흥행 스코어 반영 항목" tag="3개 항목 동일 가중" items={ITEMS.filter((x) => x.scored)} A={A} onOpen={onOpen} openKey={openKey} /><Group title="별도 진단 및 피드백" tag="스코어 미반영 · 운영 판단용" items={ITEMS.filter((x) => !x.scored)} A={A} onOpen={onOpen} openKey={openKey} /><p className="note" style={{ maxWidth: 'none' }}>분석 결과는 과거 데이터 기반의 타당성·리스크 진단입니다. 미래 방문객 수나 흥행 결과를 보장하지 않으며, 행사장 위치·일정·프로그램·우천 대안 입력이 불완전하면 일부 항목의 정확도가 떨어집니다.</p></div></main> }
function Group({ title, tag, items, A, onOpen, openKey }) { return <section className="group"><div className="grouphead"><h3>{title}</h3><span className="tag">{tag}</span><span className="line" /></div><div className="cards">{items.map((item) => <ResultCard key={item.key} item={item} A={A} onOpen={onOpen} selected={openKey === item.key} />)}</div></section> }

const mt = (label, value, detail, highlight = false) => `<div class="metric ${highlight ? 'hl' : ''}"><div class="lbl">${label}</div><div class="mv">${value}</div>${detail ? `<div class="md">${detail}</div>` : ''}</div>`
const sec = (n, title, html) => `<div class="sect"><div class="sect-h"><b>${n}</b><h4>${title}</h4><span class="line"></span></div>${html}</div>`
const recs = (list) => `<div class="recs">${list.map((r) => `<div class="rec"><span class="pri p${r.p}">${r.p === 1 ? '즉시' : r.p === 2 ? '검토' : '선택'}</span><div class="rc"><b>${r.t}</b><p>${r.d}</p>${r.e ? `<em>${r.e}</em>` : ''}</div></div>`).join('')}</div>`
function hBars(rows, unit = '명') { const W = 470, rowH = 30, padL = 118, padR = 58, maxV = Math.max(...rows.map((r) => r.v)) * 1.06, H = rows.length * rowH + 6; let s = `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:${H}px" role="img">`; rows.forEach((r, i) => { const y = i * rowH + 6, bw = r.v / maxV * (W - padL - padR); s += `<text x="${padL - 9}" y="${y + 11}" text-anchor="end" font-size="11" fill="${r.hl ? '#132434' : '#6C7D8C'}" font-weight="${r.hl ? 600 : 400}">${r.n}</text><rect x="${padL}" y="${y + 1}" width="${Math.max(bw, 2)}" height="14" rx="2" fill="${r.hl ? '#12557E' : (r.c || '#B9D0E0')}"/><text x="${padL + bw + 7}" y="${y + 12}" font-size="11" fill="${r.hl ? '#12557E' : '#3C4E5F'}" font-weight="${r.hl ? 700 : 500}">${fmt(r.v)}${unit}</text>${r.sub ? `<text x="${padL - 9}" y="${y + 22}" text-anchor="end" font-size="9.5" fill="#93A2AF">${r.sub}</text>` : ''}` }); return `${s}</svg>` }
function lineChart(labels, series, opt = {}) { const W = 470, H = opt.h || 150, padL = 34, padR = 12, padT = 12, padB = 24, all = series.flatMap((s) => s.v), mx = opt.max ?? Math.max(...all) * 1.1, mn = opt.min ?? 0, x = (i) => padL + i * (W - padL - padR) / (labels.length - 1), y = (v) => padT + (1 - (v - mn) / (mx - mn)) * (H - padT - padB); let s = `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:${H}px" role="img">`; [0, .5, 1].forEach((f) => { const yy = padT + f * (H - padT - padB); s += `<line x1="${padL}" y1="${yy}" x2="${W - padR}" y2="${yy}" stroke="#EAF0F4"/><text x="${padL - 6}" y="${yy + 3.5}" text-anchor="end" font-size="9.5" fill="#93A2AF">${fmt(mn + (1 - f) * (mx - mn))}</text>` }); series.forEach((se) => { const pts = se.v.map((v, i) => `${x(i)},${y(v)}`).join(' '); if (se.area) s += `<polygon points="${padL},${y(mn)} ${pts} ${W - padR},${y(mn)}" fill="${se.c}" opacity=".08"/>`; s += `<polyline points="${pts}" fill="none" stroke="${se.c}" stroke-width="${se.w || 2}" stroke-dasharray="${se.dash || ''}" stroke-linejoin="round"/>`; se.v.forEach((v, i) => { s += `<circle cx="${x(i)}" cy="${y(v)}" r="${se.dash ? 0 : 3}" fill="#fff" stroke="${se.c}" stroke-width="1.6"/>` }); if (se.last) s += `<text x="${x(se.v.length - 1)}" y="${y(se.v[se.v.length - 1]) - 9}" text-anchor="end" font-size="10.5" font-weight="700" fill="${se.c}">${se.last}</text>` }); labels.forEach((l, i) => { s += `<text x="${x(i)}" y="${H - 7}" text-anchor="middle" font-size="9.5" fill="#6C7D8C">${l}</text>` }); return `${s}</svg>` }
function vBars(labels, vals, hl, opt = {}) { const W = 470, H = opt.h || 132, padL = 8, padB = 22, padT = 16, mx = Math.max(...vals) * 1.12, bw = (W - padL * 2) / vals.length; let s = `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:${H}px" role="img">`; if (opt.ref) { const yy = padT + (1 - opt.ref / mx) * (H - padT - padB); s += `<line x1="${padL}" y1="${yy}" x2="${W - padL}" y2="${yy}" stroke="#A9BECD" stroke-dasharray="3 3"/><text x="${W - padL}" y="${yy - 4}" text-anchor="end" font-size="9.5" fill="#6C7D8C">${opt.refLabel || ''}</text>` } vals.forEach((v, i) => { const h = v / mx * (H - padT - padB), xx = padL + i * bw + bw * .16, ww = bw * .68, on = Array.isArray(hl) ? hl.includes(i) : i === hl; s += `<rect x="${xx}" y="${H - padB - h}" width="${ww}" height="${h}" rx="2" fill="${on ? '#12557E' : '#CBDCE8'}"/>${on ? `<text x="${xx + ww / 2}" y="${H - padB - h - 5}" text-anchor="middle" font-size="10" font-weight="700" fill="#12557E">${v}</text>` : ''}<text x="${xx + ww / 2}" y="${H - 7}" text-anchor="middle" font-size="9.5" fill="${on ? '#132434' : '#93A2AF'}" font-weight="${on ? 600 : 400}">${labels[i]}</text>` }); return `${s}</svg>` }
function gantt(rows, ps, pe, name) { const W = 470, rowH = 26, H = (rows.length + 1) * rowH + 26, all = [ps, pe, ...rows.flatMap((r) => [r.b1, r.b2])], mn = dadd(new Date(Math.min(...all)), -2), mx = dadd(new Date(Math.max(...all)), 2), span = Math.max(1, Math.round((mx - mn) / 864e5)), X = (d) => 110 + ((d - mn) / 864e5 / span) * (W - 120); let s = `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:${H}px" role="img">`; for (let i = 0; i <= 4; i++) { const d = dadd(mn, Math.round(span * i / 4)); s += `<line x1="${X(d)}" y1="16" x2="${X(d)}" y2="${H - 16}" stroke="#EAF0F4"/><text x="${X(d)}" y="11" text-anchor="middle" font-size="9.5" fill="#93A2AF">${dfmt(d)}</text>` } const bar = (y, a, b, fill, text, tc, bold) => { const x1 = X(a), x2 = Math.max(X(b), x1 + 4); return `<rect x="${x1}" y="${y}" width="${x2 - x1}" height="13" rx="2" fill="${fill}"/><text x="105" y="${y + 10}" text-anchor="end" font-size="10" fill="${tc}" font-weight="${bold ? 650 : 400}">${text.length > 13 ? `${text.slice(0, 12)}…` : text}</text>` }; s += bar(22, ps, pe, '#12557E', name, '#132434', true); rows.forEach((r, i) => { s += bar(22 + (i + 1) * rowH - 4, r.b1, r.b2, r.lv === 'direct' ? '#C2634C' : r.lv === 'near' ? '#D8A33F' : '#B9C7D2', r.n, '#3C4E5F', false) }); return `${s}</svg>` }
function gauge(pct, label, color) { const r = 44, c = 2 * Math.PI * r; return `<svg viewBox="0 0 110 110" style="width:110px;height:110px"><circle cx="55" cy="55" r="${r}" fill="none" stroke="#EAF0F4" stroke-width="11"/><circle cx="55" cy="55" r="${r}" fill="none" stroke="${color}" stroke-width="11" stroke-linecap="round" stroke-dasharray="${c * pct / 100} ${c}" transform="rotate(-90 55 55)"/><text x="55" y="54" text-anchor="middle" font-size="21" font-weight="700" fill="#132434">${Math.round(pct)}<tspan font-size="11">%</tspan></text><text x="55" y="70" text-anchor="middle" font-size="10" fill="#6C7D8C">${label}</text></svg>` }
function groupBars(groups, colors) { const W = 470, H = 150, padL = 36, padB = 30, padT = 14, mx = Math.max(...groups.flatMap((g) => g.v)) * 1.15, gw = (W - padL - 10) / groups.length; let s = `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:${H}px" role="img">`; [0, .5, 1].forEach((f) => { const yy = padT + f * (H - padT - padB); s += `<line x1="${padL}" y1="${yy}" x2="${W - 10}" y2="${yy}" stroke="#EAF0F4"/><text x="${padL - 6}" y="${yy + 3.5}" text-anchor="end" font-size="9.5" fill="#93A2AF">${fmt((1 - f) * mx)}</text>` }); groups.forEach((g, gi) => { const bw = gw * .74 / g.v.length; g.v.forEach((v, i) => { const h = v / mx * (H - padT - padB), x = padL + gi * gw + gw * .13 + i * bw; s += `<rect x="${x}" y="${H - padB - h}" width="${bw * .82}" height="${h}" rx="2" fill="${colors[i]}"/><text x="${x + bw * .41}" y="${H - padB - h - 4}" text-anchor="middle" font-size="9.5" fill="#3C4E5F">${fmt(v)}</text>` }); s += `<text x="${padL + gi * gw + gw * .5}" y="${H - 12}" text-anchor="middle" font-size="10.5" fill="#132434" font-weight="600">${g.n}</text>` }); return `${s}</svg>` }

function getDetailHtml(item, A) {
  const v = A.v, p = A.p, R = A.R, T = A.T, m = A.m
  if (item.key === 'visitor') { const rows = v.sims.map((s) => ({ n: s.n.length > 12 ? `${s.n.slice(0, 11)}…` : s.n, v: s.series[4], sub: `${s.reg} · ${s.days}일` })); rows.push({ n: '이번 기획안 목표', v: p.target, hl: true, sub: `${R.name} · ${A.days}일` }); return sec(1, '핵심 지표', `<div class="metricrow c2">${mt('목표 방문객', `${fmt(p.target)}<small>명</small>`, `${A.days}일 · 일평균 ${fmt(A.daily)}명`, true)}${mt('유사 축제 중위값', `${fmt(v.median)}<small>명</small>`, '최근 개최분 5건 기준')}${mt('중위값 대비 배수', `${round1(v.ratio)}<small>배</small>`, v.v1)}${mt('타당성 점수', `${v.s1}<small>/100</small>`, '흥행 스코어 반영')}</div>`) + sec(2, '판단 근거 및 데이터', `<div class="vizbox">${hBars(rows)}<p class="vizcap">유사 축제는 주제(${T.name})·개최 지역 특성·규모·개최 시기를 종합해 선정했습니다. 동일 지역 개최 이력 1건을 포함합니다.</p></div><div class="vizbox" style="margin-top:10px">${lineChart(YEARS, [{ v: v.yearAvg, c: '#12557E', area: true, last: fmt(v.yearAvg[4]) }, { v: YEARS.map(() => p.target), c: '#C2634C', dash: '4 3', w: 1.6, last: `목표 ${fmt(p.target)}` }])}<p class="vizcap">유사 축제 5건의 연도별 평균 방문객(진한 선)과 이번 목표(점선). 최근 4년 연평균 증가율 ${(v.simCagr * 100).toFixed(1)}%.</p><div class="legend"><span><i style="background:#12557E"></i>유사 축제 평균</span><span><i style="background:#C2634C"></i>이번 기획안 목표</span></div></div><table class="dt" style="margin-top:12px"><tr><th>유사 축제</th><th>지역</th><th class="n">2026년 실적</th><th class="n">4년 증감</th></tr>${v.sims.map((s) => `<tr><td>${s.n}</td><td style="color:var(--muted)">${s.reg}</td><td class="n">${fmt(s.series[4])}</td><td class="n" style="color:${s.series[4] >= s.series[0] ? 'var(--good)' : 'var(--risk)'}">${s.series[4] >= s.series[0] ? '+' : ''}${Math.round((s.series[4] / s.series[0] - 1) * 100)}%</td></tr>`).join('')}</table>`) + sec(3, '결과 해석', `<div class="readbox read"><p>목표 ${fmt(p.target)}명은 유사 축제 중위값 ${fmt(v.median)}명의 <strong>${round1(v.ratio)}배</strong>, 최고 실적 ${fmt(v.top)}명과 비교하면 ${round1(p.target / v.top)}배입니다. ${v.ratio > 1.3 ? '같은 주제·규모대에서 실제로 관측된 적 없는 수준이므로, 이 수치를 전제로 한 예산·인력·안전 계획은 근거가 약합니다.' : v.ratio < .8 ? '실제 관측 범위의 하단이라 달성 가능성은 높지만, 사업 규모를 설명할 때 근거가 약해질 수 있습니다.' : '실제 관측 범위 안에 있어 예산·운영 계획의 근거로 사용할 수 있습니다.'}</p><p>유사 축제군은 최근 4년간 연평균 ${(v.simCagr * 100).toFixed(1)}% ${v.simCagr > 0 ? '성장' : '감소'}했습니다. ${p.eventType === 'new' ? '다만 이번 기획안은 신규 개최로, 기존 축제의 반복 방문 기반이 없다는 점을 감안해야 합니다.' : '기존 개최 축제는 반복 방문 기반이 형성되어 있습니다.'}</p></div>`) + sec(4, '권장 수정사항', recs([{ p: v.ratio > 1.3 ? 1 : 3, t: `1차 목표를 ${fmt(v.rec1.first)}명 수준으로 조정`, d: `유사 축제 중위값 ${fmt(v.median)}명에 성장률을 반영한 값입니다. 예산·안전·인력 계획의 기준선을 이 값으로 잡으면 근거를 설명할 수 있습니다.`, e: `현재 목표 대비 ${fmt(p.target - v.rec1.first)}명 차이` }, { p: 2, t: `확장 목표 ${fmt(v.rec1.stretch)}명은 조건부로 분리 표기`, d: '셔틀 확보·숙박 연계·광역 홍보 등 선행 조건이 충족될 때만 도달 가능한 값으로 별도 관리하고, 기본 계획은 1차 목표로 수립합니다.' }, { p: 3, t: '집계 기준을 기획안에 명시', d: '유사 축제 실적은 대부분 유동인구 추정 기반입니다. 이번 축제의 집계 방식(통신사 유동인구 / 입장 게이트 / 주차 대수 환산)을 미리 정해야 개최 후 비교가 가능합니다.' }])) + `<p class="note">이 항목은 목표값의 타당성만 검토합니다. 수요 예측값을 산출하거나 예산 규모를 산정하지 않습니다.</p>` }
  if (item.key === 'trend') { const rise = T.detail.filter((d) => d.v[4] - d.v[0] > 12), fall = T.detail.filter((d) => d.v[4] - d.v[0] < -12); return sec(1, '핵심 지표', `<div class="metricrow c3">${mt('2026 관심도 지수', T.series[4], `2022년 대비 ${T.series[4] >= T.series[0] ? '+' : ''}${Math.round((T.series[4] / T.series[0] - 1) * 100)}%`, true)}${mt('연평균 증감률', `${v.tCagr > 0 ? '+' : ''}${(v.tCagr * 100).toFixed(1)}<small>%</small>`, '최근 4년')}${mt('추이 판단', v.v2, `${v.s2}점 / 100`)}</div>`) + sec(2, '판단 근거 및 데이터', `<div class="vizbox">${lineChart(YEARS, [{ v: T.series, c: v.v2 === '하락' ? '#C2634C' : '#12557E', area: true, last: T.series[4] }], { max: 110 })}<p class="vizcap">주제 키워드군(${T.kw})의 통합 검색 관심도. 최댓값 100 기준 상대 지수입니다.</p></div><table class="dt" style="margin-top:12px"><tr><th>세부 키워드</th><th class="n">2022</th><th class="n">2026</th><th>추이</th></tr>${T.detail.map((d) => `<tr><td>${d.k}</td><td class="n" style="color:var(--muted)">${d.v[0]}</td><td class="n"><b>${d.v[4]}</b></td><td><span class="tagsm ${d.v[4] - d.v[0] > 12 ? 'g' : d.v[4] - d.v[0] < -12 ? 'r' : 'n'}">${d.d}</span></td></tr>`).join('')}</table><p class="vizcap" style="margin-top:9px">프로그램 구성에 포함된 요소별로 관심 흐름이 다릅니다. 같은 주제 안에서도 상승 키워드와 하락 키워드를 구분해 배치 비중을 정하는 근거로 사용합니다.</p>`) + sec(3, '결과 해석', `<div class="readbox read"><p>${T.name} 주제는 최근 4년간 연평균 ${(v.tCagr * 100).toFixed(1)}% ${v.tCagr > 0 ? '상승' : '하락'}해 <strong>${v.v2}</strong> 흐름으로 판단했습니다.</p><p>${rise.length ? `세부 키워드 중 ${rise.map((d) => d.k).join(', ')}이(가) 상승 폭이 큽니다. ` : ''}${fall.length ? `반대로 ${fall.map((d) => d.k).join(', ')}은(는) 하락 구간에 들어섰습니다. ` : ''}${rise.some((d) => d.d.includes('확산')) ? '다만 급상승 키워드는 전국 도입이 빠르게 늘어 차별화 효과가 줄어드는 구간입니다.' : (!rise.length && !fall.length ? '세부 키워드 간 편차는 크지 않습니다.' : '')}</p></div>`) + sec(4, '기획 제안', recs([...rise.slice(0, 1).map((d) => ({ p: 2, t: `${d.k}을(를) 대표 프로그램으로 전면 배치`, d: `4년간 ${Math.round((d.v[4] / d.v[0] - 1) * 100)}% 상승한 키워드입니다. 홍보 문구와 대표 이미지의 기준을 이 요소로 맞추면 검색 유입과 기획 내용이 일치합니다.` })), ...T.detail.filter((d) => d.d.includes('확산')).map((d) => ({ p: 2, t: `${d.k}은(는) 차별화 요소가 아닌 기본 연출로 취급`, d: '전국 도입이 빠르게 늘어 단독 홍보 포인트로는 변별력이 낮습니다. 예산 비중을 줄이고 대표 프로그램의 보조 연출로 배치하는 편이 효율적입니다.' })), ...fall.slice(0, 1).map((d) => ({ p: d.v[4] < 60 ? 1 : 3, t: `${d.k} 비중 축소 검토`, d: `관심도가 ${Math.round((1 - d.v[4] / d.v[0]) * 100)}% 감소했습니다. 유지하려면 체험형·야간형으로 형식을 바꾸는 전제가 필요합니다.` })), { p: 3, t: '개최 월의 계절 요인은 별도 항목에서 확인', d: '이 항목은 주제 관심도의 시간 흐름만 봅니다. 개최 시기가 적절한지는 지역·시기 관광수요 적합성에서 판단합니다.' }])) + `<p class="note">트렌드 핏은 개최 월의 계절성 자체를 평가 기준에 포함하지 않습니다.</p>` }
  if (item.key === 'demand') { const ac = R.access; return sec(1, '핵심 지표', `<div class="metricrow c2">${mt('적합성 점수', `${v.s3}<small>/100</small>`, '평상시 25% · 월별 50% · 접근성 25%', true)}${mt(`${m + 1}월 관광수요 지수`, v.mIdx, `연중 ${v.mRank}위 (연평균 100)`)}${mt('평상시 지역 관광수요', `${R.baseDemand}<small>/100</small>`, `${R.annual} · ${R.baseNote}`)}${mt('행사장 접근성', `${v.accScore}<small>/100</small>`, `대중교통 ${ac.transitScore} · 주차 충족률 ${Math.round(v.parkRatio * 100)}%`)}</div>`) + sec(2, '판단 근거 및 데이터', `<div class="vizbox">${vBars(MONTHS, R.monthly, m, { ref: 100, refLabel: '연평균 100' })}<p class="vizcap">${R.name}의 최근 5년 월별 관광수요 지수(연평균 100 기준). 개최 월 ${m + 1}월은 ${v.mIdx}로 연중 ${v.mRank}위입니다.</p></div><div class="vizbox" style="margin-top:10px"><div class="metricrow c2" style="gap:8px">${mt('서울 도심 기준 이동', ac.car, `약 ${ac.km}km`)}${mt('철도', ac.train, ac.station)}${mt('확보 주차면수', `${fmt(p.parking)}<small>면</small>`, `권장 ${fmt(v.parkNeed)}면 · 충족률 ${Math.round(v.parkRatio * 100)}%`)}${mt('대중교통 접근성', `${ac.transitScore}<small>/100</small>`, ac.transitNote)}</div><p class="vizcap">권장 주차면수는 일평균 ${fmt(A.daily)}명 · 자가용 분담 60% · 동승 2.8명 · 회전율 3.5회를 적용한 값입니다.</p></div><div class="metricrow c2" style="margin-top:10px">${mt('외지인 방문 비율', `${R.outRatio}<small>%</small>`, '지역 내 소비 유발 기반')}${mt('체류형 방문 비율', `${R.stayRatio}<small>%</small>`, '숙박을 동반한 방문')}</div>`) + sec(3, '결과 해석', `<div class="readbox read"><p>${R.name}의 평상시 관광수요는 ${R.baseDemand}점으로 ${R.baseNote}입니다. 반면 개최 월인 ${m + 1}월은 지수 ${v.mIdx}로 연중 ${v.mRank}위여서, <strong>시기 선택 자체는 ${v.mIdx >= 115 ? '유리' : '무난'}합니다</strong>.</p><p>${v.accScore < 60 ? `전체 점수를 낮추는 요인은 접근성입니다. 주차 충족률 ${Math.round(v.parkRatio * 100)}%, 대중교통 ${ac.transitScore}점으로, ${ac.transitNote}. 목표 방문객이 몰리는 피크 시간대에 진입 동선이 병목이 될 수 있습니다.` : `접근성도 ${v.accScore}점으로 무리가 없어, 지역·시기 조합에서 큰 제약은 확인되지 않습니다.`}</p></div>`) + sec(4, '권장 수정사항', recs([...(v.parkRatio < .9 ? [{ p: v.parkRatio < .7 ? 1 : 2, t: `외곽 임시주차장 ${fmt(Math.max(0, v.parkNeed - p.parking))}면 확보 + 셔틀 연계`, d: `현재 ${fmt(p.parking)}면으로 권장 ${fmt(v.parkNeed)}면의 ${Math.round(v.parkRatio * 100)}% 수준입니다. 행사장 인접 확보가 어렵다면 외곽 2~3개소로 분산하고 10분 간격 셔틀로 연결하는 방식이 일반적입니다.` }] : []), ...(ac.transitScore < 65 ? [{ p: 2, t: `${ac.station.split('·')[0].trim()}·터미널 ↔ 행사장 순환 셔틀 운행`, d: '정기 노선이 부족해 대중교통 이용자가 마지막 구간에서 이탈할 수 있습니다. 운행 시간은 야간 프로그램 종료 후 1시간까지 확보해야 체류 시간이 유지됩니다.' }] : []), { p: 3, t: '수도권 왕복 교통 상품 연계', d: `외지인 비율이 ${R.outRatio}%로 높아, 왕복 전세버스·철도 연계 상품을 사전 판매하면 방문 확정 인원을 미리 파악할 수 있습니다.` }])) + `<p class="note">이 항목은 평상시 지역 관광수요와 월별 추이, 접근성만 평가합니다. 특정 개최일에 주변 행사가 겹치는지는 일정 중복·혼잡 리스크에서 별도로 진단합니다.</p>` }
  if (item.key === 'overlap') {
    const sd = dparse(p.start), ed = dparse(p.end), lvName = { direct: '기간 중복', near: '인접(±3일)', watch: '주의(±7일)' }, overlapRecs = []
    if (v.best && v.best.w < v.nDirect * 3 + v.nNear) overlapRecs.push({ p: v.nDirect >= 2 ? 1 : 2, t: `개최일 ${v.best.off > 0 ? `${v.best.off}일 순연` : `${Math.abs(v.best.off)}일 앞당김`} 검토 (${dfmt(dadd(sd, v.best.off))}~${dfmt(dadd(ed, v.best.off))})`, d: `이 구간에서는 기간 직접 중복이 ${v.best.c.filter((x) => x.lv === 'direct').length}건으로 줄어듭니다. 일정 확정 전이라면 가장 비용이 적게 드는 대응입니다.`, e: `이력 기준 비교이며, 상대 행사가 일정을 변경할 가능성은 반영되지 않았습니다.${dadd(sd, v.best.off).getMonth() !== sd.getMonth() ? ' 개최 월이 바뀌므로 관광수요·기상 항목을 다시 분석해야 합니다.' : ''}` })
    if (v.nDirect) overlapRecs.push({ p: 1, t: '중복 행사와 셔틀·숙박 공동 운영 협의', d: `${v.cf.filter((c) => c.lv === 'direct').map((c) => c.n).join(', ')}와 권역 순환 셔틀을 공동 운영하면 경합을 연계로 바꿀 수 있습니다. 숙박은 개최 4개월 전 블록 예약으로 객실을 선점해야 합니다.` })
    if (v.nDirect || v.nNear) overlapRecs.push({ p: 2, t: '요일 배치 조정으로 피크 분산', d: '중복 행사와 주말 피크가 겹치면 혼잡이 집중됩니다. 대표 프로그램을 금요일 야간·일요일 오전으로 분산 배치하면 동시 체류 인원을 낮출 수 있습니다.' })
    overlapRecs.push({ p: 3, t: '차별화 지점을 홍보 문구에 명시', d: `인접 행사와 방문 목적이 겹치지 않도록, 이번 축제만의 프로그램(${A.progs.slice(0, 2).map((x) => x.n).join(', ') || '대표 프로그램'})을 전면에 배치합니다.` })
    return sec(1, '핵심 지표', `<div class="metricrow c3">${mt('위험 수준', v.v4, '스코어 미반영 진단', true)}${mt('기간 직접 중복', `${v.nDirect}<small>건</small>`, '반경 60km 이내')}${mt('인접 시기 행사', `${v.nNear}<small>건</small>`, '±3일 이내')}</div><div class="metricrow c2" style="margin-top:9px">${mt('숙박 경합 압력', `${v.stayPressure}<small>%</small>`, `중복 행사 숙박 수요 추정 ${fmt(v.rivalStayDemand)}명 / 권역 수용 ${fmt(v.stayRooms * 2.2)}명`)}${mt('검토 범위', `${dfmt(sd)}~${dfmt(ed)}`, '최근 5년 중 3회 이상 개최된 행사만 집계')}</div>`) + sec(2, '판단 근거 및 데이터', v.cf.length ? `<div class="vizbox">${gantt(v.cf, sd, ed, p.name || '이번 축제')}<p class="vizcap">진한 막대가 이번 기획안의 개최 기간입니다. 빨간색은 기간이 겹치는 행사, 주황색은 전후 3일 내 인접 행사입니다.</p><div class="legend"><span><i style="background:#12557E"></i>이번 축제</span><span><i style="background:#C2634C"></i>기간 중복</span><span><i style="background:#D8A33F"></i>인접</span><span><i style="background:#B9C7D2"></i>주의 범위</span></div></div><table class="dt" style="margin-top:12px"><tr><th>행사명</th><th>권역</th><th class="n">거리</th><th class="n">규모</th><th>구분</th></tr>${v.cf.map((c) => `<tr class="${c.lv === 'direct' ? 'hit2' : c.lv === 'near' ? 'hit' : ''}"><td><b>${c.n}</b><div style="color:var(--muted);font-size:11px">${dfmt(c.b1)}~${dfmt(c.b2)} · 최근 5년 ${c.held}회</div></td><td style="color:var(--muted)">${c.reg}</td><td class="n">${c.km}km</td><td class="n">${fmt(c.scale)}명</td><td><span class="tagsm ${c.lv === 'direct' ? 'r' : c.lv === 'near' ? 'w' : 'n'}">${lvName[c.lv]}</span></td></tr>`).join('')}</table>` : `<div class="vizbox"><p class="read" style="font-size:12.5px">반경 80km · ±7일 범위에서 최근 5년 중 3회 이상 반복 개최된 행사가 확인되지 않았습니다.</p></div>`) + sec(3, '결과 해석', `<div class="readbox read"><p>${v.nDirect ? `개최 기간에 직접 겹치는 행사가 <strong>${v.nDirect}건</strong> 있습니다. 가장 가까운 사례는 ${v.cf[0].n}(${v.cf[0].km}km, 최근 5년 ${v.cf[0].held}회 개최, 규모 ${fmt(v.cf[0].scale)}명)입니다. 같은 권역 방문객이 두 행사로 나뉘고, 숙박·주차·셔틀 인력이 동시에 경합합니다.` : v.nNear ? `기간이 직접 겹치는 행사는 없습니다. 다만 전후 3일 내 ${v.nNear}건이 있어 숙박 예약과 홍보 노출이 분산될 수 있습니다.` : '같은 시기 인접 권역의 반복 개최 행사가 확인되지 않아, 일정 측면의 경합 요인은 낮습니다.'}</p><p>${v.best && v.best.w < v.nDirect * 3 + v.nNear ? `개최일을 ${v.best.off > 0 ? '+' : ''}${v.best.off}일 이동하면 중복 가중치 ${v.nDirect * 3 + v.nNear}에서 ${v.best.w}로 낮아집니다(${dfmt(dadd(sd, v.best.off))}~${dfmt(dadd(ed, v.best.off))}).` : '검토 범위(±14일) 안에서 현재 일정보다 유리한 대체 구간은 확인되지 않았습니다.'}</p></div>`) + sec(4, '권장 수정사항', recs(overlapRecs)) + `<p class="note">이 진단은 행사 이력만으로 판단하며 일반 관광객 수를 기준에 포함하지 않습니다. 흥행 스코어에는 반영되지 않습니다.</p>`
  }
  if (item.key === 'weather') { const W = R.weather; return sec(1, '핵심 지표', `<div class="metricrow c2">${mt('행사 구조 취약도', `${v.wRisk}<small>/100</small>`, '강수 40% · 야외 비중 35% · 대체 수용 25%', true)}${mt(`${m + 1}월 강수 발생률`, `${v.rainP}<small>%</small>`, `최근 10년 중 ${W.rainYears[m]}년 · 일 10mm 이상 ${W.heavyYears[m]}년`)}${mt('야외 프로그램 비중', `${p.outdoor}<small>%</small>`, `${A.progs.filter((x) => x.out).length}개 프로그램이 야외`)}${mt('실내 대체 수용률', `${Math.round(v.shelterCov)}<small>%</small>`, `대체 ${fmt(p.shelter)}석 / 동시 체류 추정 ${fmt(v.concurrent)}명`)}</div>`) + sec(2, '판단 근거 및 데이터', `<div class="vizbox">${vBars(MONTHS, W.rainYears.map((x) => x * 10), m, { h: 130 })}<p class="vizcap">${R.name} 월별 강수 발생률(최근 10년 중 강수 관측 연수 × 10%). ${W.note}.</p></div><div class="vizbox" style="margin-top:10px;display:flex;gap:16px;align-items:center">${gauge(p.outdoor, '야외 비중', '#C2634C')}<div style="flex:1"><table class="dt"><tr><th>취약 요소</th><th>발생 이력</th></tr>${v.wFlags.map((f) => `<tr><td><b>${f.t}</b> <span class="tagsm ${f.risk ? 'r' : 'n'}">${f.risk ? '취약' : '해당 없음'}</span><div style="color:var(--muted);font-size:11px;margin-top:2px">${f.p}</div></td><td style="font-size:11.5px">${f.d}</td></tr>`).join('')}</table></div></div><p class="vizcap" style="margin-top:9px">동시 체류 추정 인원은 일평균 ${fmt(A.daily)}명의 35%를 적용한 값입니다. 우천 대안 설정은 "${{ none: '없음', partial: '일부 확보', full: '충분' }[p.rainplan]}"입니다.</p>`) + sec(3, '결과 해석', `<div class="readbox read"><p>${m + 1}월 동일 시기에 강수가 관측된 해는 최근 10년 중 ${W.rainYears[m]}년(${v.rainP}%)입니다. 여기에 야외 프로그램 비중 ${p.outdoor}%와 실내 대체 수용률 ${Math.round(v.shelterCov)}%를 결합하면 행사 구조의 취약도는 <strong>${v.wRisk}점(${v.v5})</strong>입니다.</p><p>${v.wFlags.filter((f) => f.risk).length ? `특히 ${v.wFlags.filter((f) => f.risk).map((f) => f.t).join(' · ')} 요소가 현재 프로그램 구성과 직접 맞물립니다. ${v.wFlags.filter((f) => f.risk)[0].p} 계획이 기상 조건에 따라 취소 또는 축소될 수 있습니다.` : '현재 프로그램 구성에서 기상 조건과 직접 충돌하는 요소는 크지 않습니다.'}</p><p>강수 시 동시 체류 ${fmt(v.concurrent)}명 중 실내로 수용 가능한 인원은 ${fmt(p.shelter)}명입니다. ${v.shelterCov < 30 ? '나머지 인원은 대기·귀가로 이어지며 만족도와 체류 시간이 함께 떨어집니다.' : '대체 동선을 안내하면 상당수를 유지할 수 있습니다.'}</p></div>`) + sec(4, '권장 수정사항', recs([{ p: v.shelterCov < 25 ? 1 : 2, t: `실내 대체 수용 인원 ${fmt(Math.max(0, Math.round(v.concurrent * .5 - p.shelter)))}명 추가 확보`, d: `동시 체류 추정 ${fmt(v.concurrent)}명의 절반 수준(${fmt(Math.round(v.concurrent * .5))}명)을 대체 수용 목표로 잡는 방식이 일반적입니다. 인근 체육관·문화예술회관·대형 텐트 구조물이 후보가 됩니다.` }, ...v.wFlags.filter((f) => f.risk).map((f) => ({ p: f.t === '강수' ? 1 : 2, t: f.t === '강수' ? '우천 판단 시점과 환불·연기 기준 공지' : f.t === '강풍' ? '풍속 기준과 대체 공연 절차를 사전 확정' : f.t === '안개 · 시정' ? '시정 불량 시 대체 콘텐츠 준비' : '야간 방한 대응 배치', d: f.t === '강수' ? '유료 프로그램이 있다면 우천 시 연기·환불 기준을 사전 공지해야 민원이 줄어듭니다. 판단 시점은 행사 시작 3시간 전으로 고정하는 방식이 흔합니다.' : `${f.d}. ${f.p}에 대한 대체 운영 절차를 운영 매뉴얼에 미리 넣어 두면 현장 혼선이 줄어듭니다.` })), ...(p.rainplan === 'none' ? [{ p: 1, t: '우천 대안을 기획안에 신설', d: '현재 우천 대안이 없음으로 입력되어 있습니다. 대체 공간과 축소 운영 시나리오가 없으면 강수 시 행사 전체가 중단됩니다.' }] : [])])) + `<p class="note">이 진단은 미래 날씨를 예측하지 않습니다. 과거 동일 시기 기상 통계와 기획안의 구조적 취약성만 봅니다. 흥행 스코어에는 반영되지 않습니다.</p>` }
  const P = R.poi, byType = (t) => R.poiList.filter((x) => x.t === t); return sec(1, '핵심 지표', `<div class="metricrow c3">${mt('연계 잠재력', `${v.s6}<small>/100</small>`, v.v6, true)}${mt('반경 15km 관광지', `${P.r15.tour}<small>곳</small>`, `반경 5km ${P.r5.tour}곳`)}${mt('체류 수용률', `${Math.round(v.stayCov)}<small>%</small>`, `객실 ${fmt(P.r15.rooms)}실 기준`)}</div>`) + sec(2, '판단 근거 및 데이터', `<div class="vizbox">${groupBars([{ n: '관광지', v: [P.r5.tour, P.r15.tour] }, { n: '음식점 · 상권', v: [P.r5.food, P.r15.food] }, { n: '숙박', v: [P.r5.stay, P.r15.stay] }], ['#12557E', '#A9C9DD'])}<div class="legend"><span><i style="background:#12557E"></i>반경 5km</span><span><i style="background:#A9C9DD"></i>반경 15km</span></div><p class="vizcap">행사장(${p.venue || '미입력'}) 기준 POI 집계입니다.</p></div><table class="dt" style="margin-top:12px"><tr><th>주요 연계 자원</th><th>구분</th><th class="n">거리</th></tr>${R.poiList.map((x) => `<tr><td><b>${x.n}</b><div style="color:var(--muted);font-size:11px">${x.note}</div></td><td><span class="tagsm n">${x.t}</span></td><td class="n">${x.km}km</td></tr>`).join('')}</table><div class="metricrow c3" style="margin-top:11px">${mt('숙박 수용 인원', `${fmt(v.stayCap)}<small>명</small>`, '객실당 2.2명 적용')}${mt('일평균 방문객', `${fmt(A.daily)}<small>명</small>`, `${A.days}일 기준`)}${mt('상권 규모', `${fmt(P.r15.food)}<small>개</small>`, '음식점 · 판매 시설')}</div>`) + sec(3, '결과 해석', `<div class="readbox read"><p>반경 15km 안에 관광지 ${P.r15.tour}곳, 음식점·상권 ${fmt(P.r15.food)}개, 숙박 ${P.r15.stay}곳(객실 ${fmt(P.r15.rooms)}실)이 있습니다. ${byType('관광지')[0] ? `특히 ${byType('관광지')[0].n}(${byType('관광지')[0].km}km)은 ${byType('관광지')[0].note}으로, 축제 주제와 직접 연결할 수 있는 자원입니다.` : ''}</p><p>반면 숙박 수용 인원 ${fmt(v.stayCap)}명은 일평균 방문객 ${fmt(A.daily)}명의 <strong>${Math.round(v.stayCov)}%</strong> 수준입니다. ${v.stayCov < 40 ? '체류형 방문을 늘리려면 객실 외 숙박 자원을 추가로 확보해야 합니다. 현재 구조에서는 당일 방문 중심으로 운영될 가능성이 큽니다.' : '체류형 방문을 흡수할 여력이 있는 편입니다.'}</p></div>`) + sec(4, '기획 제안', recs([{ p: 2, t: `관광 확장 — ${byType('관광지')[0]?.n || '인근 관광지'} 연계 통합권`, d: `축제 입장 또는 프로그램 예약자에게 ${byType('관광지').slice(0, 2).map((x) => x.n).join(' · ')} 할인 통합권을 제공합니다. 방문 동선이 행사장 밖으로 확장되면서 지역 체류 시간이 늘어납니다.`, e: `대상 자원: 반경 15km 관광지 ${P.r15.tour}곳` }, { p: 2, t: `상권 연계 — ${byType('상권')[0]?.n || '인근 상권'} 야간 영업 연장`, d: `행사 기간 중 ${byType('상권')[0]?.n || '인근 상권'} 점포의 영업 시간을 프로그램 종료 시각에 맞춰 연장하고, 축제 팔찌 제시 시 할인·환급을 적용합니다. 소비가 행사장 부스가 아닌 기존 상권으로 흐르게 하는 방식입니다.`, e: `대상 규모: 음식점 · 판매 시설 ${fmt(P.r15.food)}개` }, { p: v.stayCov < 40 ? 1 : 3, t: '체류 연장 — 1박 2일 코스 상품과 임시 숙박 자원 확보', d: `현재 객실 수용률이 ${Math.round(v.stayCov)}%이므로, 정규 숙박만으로는 체류형 수요를 받기 어렵습니다. 캠핑·농가민박·유휴 시설을 한시 등록해 보완하고, 야간 프로그램 + 다음 날 오전 관광지를 묶은 1박 2일 코스를 사전 판매합니다.`, e: `부족 추정: 약 ${fmt(Math.max(0, Math.round((A.daily * .4 - v.stayCap) / 2.2)))}실` }])) + `<p class="note">관광 연계 잠재력은 흥행 스코어에 반영되지 않는 별도 진단입니다. POI 수와 분포를 근거로 관광 확장 · 상권 연계 · 체류 연장의 세 관점에서 제안합니다.</p>`
}

function Panel({ item, A, onClose, onEdit, onMove }) { if (!item) return null; const d = cardData(item, A); return <><div className="scrim on" onClick={onClose} /><aside className="panel on" aria-hidden="false" aria-label={`${item.no}. ${item.name} 상세 분석`}><div className="p-head"><div className="p-nav"><button className="iconbtn" onClick={() => onMove(-1)} disabled={item.index === 0} title="이전 항목">‹</button><button className="iconbtn" onClick={() => onMove(1)} disabled={item.index === ITEMS.length - 1} title="다음 항목">›</button><span className="idx">{item.index + 1} / {ITEMS.length} 항목</span><div className="spacer" /><button className="iconbtn" onClick={onClose} title="닫기 (Esc)">×</button></div><div className="p-title"><div><h2>{item.no}. {item.name}</h2><p className="p-scope">{item.scored ? '흥행 스코어 반영' : '별도 진단'} · {item.scope}</p></div><span className={levelClass(d.tone)}>{d.pill}</span></div></div><div className="p-body" dangerouslySetInnerHTML={{ __html: getDetailHtml(item, A) }} /><div className="p-foot"><Button small primary onClick={onEdit}>이 항목 보완하러 가기</Button><span className="spacer" /><Button small onClick={onClose}>닫기</Button></div></aside></> }

function ReportScreen({ A, onBack, onPrint }) { const cards = ITEMS.map((item) => ({ item, data: cardData(item, A) })); const recommendations = useMemo(() => { const doc = new DOMParser().parseFromString(ITEMS.map((item) => getDetailHtml(item, A)).join(''), 'text/html'); return [...doc.querySelectorAll('.rec')].map((el, i) => ({ source: ITEMS.find((item) => getDetailHtml(item, A).includes(el.querySelector('b')?.textContent || ''))?.name || '평가 항목', title: el.querySelector('b')?.textContent || '', text: el.querySelector('p')?.textContent || '', priority: el.querySelector('.pri')?.className.match(/p([123])/)?.[1] * 1 || 3, i })).sort((a, b) => a.priority - b.priority || a.i - b.i) }, [A]); return <main className="screen active"><div className="wrap"><div className="plan-bar noprint"><div><div className="plan-title">최종 리포트</div><div className="plan-meta">6개 평가 항목의 판단과 권장 수정사항을 한 장으로 정리했습니다.</div></div><span className="spacer" /><Button small onClick={onBack}>결과로 돌아가기</Button><Button small primary onClick={onPrint}>인쇄 / PDF 저장</Button></div><div className="rpt"><div className="rpt-head"><div><div className="lbl">축제 흥행 사전 검증 리포트</div><h2 className="report-title">{A.p.name}</h2><div className="plan-meta">{A.p.org || A.R.name}<i>|</i>{A.p.venue}<i>|</i>{A.p.start} ~ {A.p.end} ({A.days}일)<i>|</i>목표 {fmt(A.p.target)}명</div></div><div className="report-score"><div className="lbl">종합 흥행 스코어</div><b>{A.composite}</b><div className="lbl">등급 {A.grade} · {A.gradeNote}</div></div></div><ReportGroup title="흥행 스코어 반영 항목" tag="3개 항목 동일 가중" cards={cards.filter((x) => x.item.scored)} /><ReportGroup title="별도 진단" tag="스코어 미반영" cards={cards.filter((x) => !x.item.scored)} /><section className="rpt-sec"><h3>권장 수정사항 {recommendations.length}건</h3><div className="rpt-list">{recommendations.map((r) => <div className="rpt-row" key={`${r.source}-${r.title}-${r.i}`}><div><span className={`pri p${r.priority}`}>{r.priority === 1 ? '즉시' : r.priority === 2 ? '검토' : '선택'}</span></div><div><b>{r.title}</b><p>{r.text}</p><div className="src">{r.source}</div></div></div>)}</div></section><section className="rpt-sec"><p className="note report-note">이 리포트는 유사 축제·검색 관심도·지역 관광수요·행사 이력·기상 통계·주변 POI의 과거 데이터를 근거로 한 타당성 및 리스크 진단입니다. 미래 흥행을 보장하지 않으며, 입력 정보가 변경되면 결과도 달라집니다. 본 화면은 예시 데이터로 동작하는 프로토타입입니다.</p></section></div></div></main> }
function ReportGroup({ title, tag, cards }) { return <section className="rpt-sec"><h3>{title} <span className="tag" style={{ fontWeight: 400, fontSize: '11.5px', color: 'var(--muted)' }}>{tag}</span></h3><div className="rpt-grid">{cards.map(({ item, data }) => <div className="rpt-item" key={item.key}><div className="t"><b>{item.name}</b><span className={levelClass(data.tone)}>{data.pill}</span></div><div className="report-metric">{data.metric} <span>{data.unit}</span></div><p>{data.read}</p></div>)}</div></section> }

export default function App() {
  const [stage, setStage] = useState('input'), [step, setStep] = useState(1), [plan, setPlan] = useState({ name: '', org: '', festivalThemes: [{ type: '', topic: '' }], target: 0, eventType: 'new', firstHeldYear: null, region: 'yeongwol', venueType: 'outdoor', venue: '', start: '', end: '', parking: 0, programs: [], outdoor: 85, rainplan: 'partial', shelter: 0 }), [analysis, setAnalysis] = useState(null), [openKey, setOpenKey] = useState(null)
  const A = useMemo(() => analysis || (stage === 'input' ? null : analyze(plan)), [analysis, plan, stage]), index = ITEMS.findIndex((x) => x.key === openKey), openItem = index >= 0 ? { ...ITEMS[index], index } : null
  useEffect(() => { window.scrollTo({ top: 0, behavior: 'instant' }) }, [stage, step])
  useEffect(() => { const f = (e) => { if (e.key === 'Escape') setOpenKey(null); if (index >= 0 && e.key === 'ArrowLeft' && index > 0) setOpenKey(ITEMS[index - 1].key); if (index >= 0 && e.key === 'ArrowRight' && index < ITEMS.length - 1) setOpenKey(ITEMS[index + 1].key) }; window.addEventListener('keydown', f); return () => window.removeEventListener('keydown', f) }, [index])
  const home = () => { setOpenKey(null); setStage('input'); setStep(1); setAnalysis(null) }, goEdit = () => { setOpenKey(null); setStep(1); setStage('input') }, finish = () => { setAnalysis(analyze(plan)); setStage('result') }
  return <><Header stage={stage} onHome={home} />{stage === 'input' && <FormScreen plan={plan} setPlan={setPlan} step={step} setStep={setStep} onReview={(p) => { setPlan(p); setStage('review') }} />}{stage === 'review' && <ReviewScreen plan={plan} onEdit={() => setStage('input')} onAnalyze={() => setStage('loading')} />}{stage === 'loading' && <LoadingScreen plan={plan} onDone={finish} />}{stage === 'result' && A && <ResultScreen A={A} onEdit={goEdit} onReport={() => setStage('report')} onOpen={setOpenKey} openKey={openKey} />}{stage === 'report' && A && <ReportScreen A={A} onBack={() => setStage('result')} onPrint={() => window.print()} />}{openItem && A && <Panel item={openItem} A={A} onClose={() => setOpenKey(null)} onEdit={goEdit} onMove={(direction) => { const next = ITEMS[index + direction]; if (next) setOpenKey(next.key) }} />}</>
}
